import { readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { startTestDb, type TestDb } from "./harness.ts";

// GH-10: the délégations of the Grand Tunis come with migration 0009 (a one-time OpenStreetMap extract,
// generated by infra/data/zones/extract.mjs; ODbL, © OpenStreetMap contributors). Every database that is
// migrated has them, so a test needs no seed.
const ZONES_DIR = new URL("../../../../infra/data/zones/", import.meta.url);
const read = (name: string) => readFileSync(fileURLToPath(new URL(name, ZONES_DIR)), "utf8");
const MIGRATION = fileURLToPath(new URL("../../migrations/0009_zones_grand_tunis.sql", import.meta.url));

let db: TestDb;
const zoneAt = async (lon: number, lat: number) =>
  (await db.superClient.query("select z.name, z.governorate from core.zones z where z.id = core.zone_at($1, $2)", [lon, lat])).rows[0] as
    | { name: string; governorate: string }
    | undefined;

beforeAll(async () => {
  db = await startTestDb();
});
afterAll(async () => {
  await db?.stop();
});

describe("R201_T04 the délégations of the Grand Tunis (migration 0009)", () => {
  it("a freshly migrated database has the 48 délégations of the four governorates, all active, each with a polygon", async () => {
    const rows = (
      await db.superClient.query(
        "select governorate, count(*)::int as n, bool_and(active) as active, bool_and(area is not null) as polygon from core.zones group by 1 order by 1",
      )
    ).rows;
    expect(rows).toEqual([
      { governorate: "Ariana", n: 7, active: true, polygon: true },
      { governorate: "Ben Arous", n: 12, active: true, polygon: true },
      { governorate: "Manouba", n: 8, active: true, polygon: true },
      { governorate: "Tunis", n: 21, active: true, polygon: true },
    ]);
  });

  it("every zone has a valid, non-empty multipolygon", async () => {
    const bad = (
      await db.superClient.query(
        `select name from core.zones
          where area is null or not public.ST_IsValid(area::public.geometry)
             or public.ST_IsEmpty(area::public.geometry) or public.GeometryType(area::public.geometry) <> 'MULTIPOLYGON'`,
      )
    ).rows;
    expect(bad).toEqual([]);
  });

  it("a point inside, a point outside, and a point of each governorate", async () => {
    expect(await zoneAt(10.1815, 36.8065)).toMatchObject({ governorate: "Tunis" }); // centre of Tunis
    expect(await zoneAt(10.1647, 36.8665)).toMatchObject({ governorate: "Ariana" }); // Ariana ville
    expect(await zoneAt(10.2189, 36.7531)).toMatchObject({ governorate: "Ben Arous" });
    expect(await zoneAt(10.0986, 36.8081)).toMatchObject({ governorate: "Manouba" });
    expect(await zoneAt(10.76, 34.74)).toBeUndefined(); // Sfax: outside the Grand Tunis
    expect(await zoneAt(2.35, 48.85)).toBeUndefined(); // Paris
  });

  it("two délégations do not overlap by more than a sliver (shared borders are shared points)", async () => {
    const r = await db.superClient.query(
      `select a.name as a, b.name as b,
              public.ST_Area(public.ST_Intersection(a.area::public.geometry, b.area::public.geometry)::public.geography) as m2
         from core.zones a join core.zones b on a.id < b.id and public.ST_Intersects(a.area, b.area)
        where public.ST_Area(public.ST_Intersection(a.area::public.geometry, b.area::public.geometry)::public.geography) > 1000
        order by m2 desc`,
    );
    expect(r.rows).toEqual([]);
  });

  it("the synthetic squares of the other tests (lon 10 to 10.4, lat 36 to 36.1) overlap no real délégation", async () => {
    const r = await db.superClient.query(
      `select name from core.zones
        where public.ST_Intersects(area, public.ST_MakeEnvelope(9.9, 35.9, 10.5, 36.2, 4326)::public.geography)`,
    );
    expect(r.rows).toEqual([]);
  });

  it("the migration is generated from delegations.geojson and is the only copy of the data in the API", () => {
    const sql = readFileSync(MIGRATION, "utf8");
    const geo = JSON.parse(read("delegations.geojson")) as { features: { properties: { name: string } }[] };
    expect(geo.features).toHaveLength(48);
    for (const f of geo.features) expect(sql, f.properties.name).toContain(`'${f.properties.name.replaceAll("'", "''")}'`);
    expect(sql).not.toMatch(/begin;|commit;/i); // the runner already wraps a migration in one transaction
  });

  it("carries the ODbL credit in the data, the seed and the attribution file", () => {
    for (const [name, text] of [["delegations.geojson", read("delegations.geojson")], ["0009", readFileSync(MIGRATION, "utf8")], ["ATTRIBUTION.md", read("ATTRIBUTION.md")]])
      expect(text, name).toContain("© OpenStreetMap contributors");
    expect(read("ATTRIBUTION.md")).toContain("ODbL");
  });
});
